let M = tolower(tostring(split('{Machine}', '/')[-1]));
let WindowStart = todatetime('{TimeRange:startISO}');
let WindowEnd = todatetime('{TimeRange:endISO}');
let WindowSpan = WindowEnd - WindowStart;
let Step = case(WindowSpan <= 6h, 10m, WindowSpan <= 2d, 1h, WindowSpan <= 8d, 2h, WindowSpan <= 16d, 6h, 12h);
let Num = (v:real, digits:int) { replace_regex(tostring(round(v, digits)), @"\.0+$", "") };
let AgeText = (ts:datetime) {
    let mins = datetime_diff('minute', now(), ts);
    case(isnull(ts), 'none', mins < 2, 'just now', mins < 120, strcat(mins, ' min ago'), mins < 2880, strcat(Num(mins / 60.0, 1), ' h ago'), strcat(Num(mins / 1440.0, 1), ' d ago'))
};
let CpuRaw = Perf
| where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M
| where ObjectName in ('Processor Information', 'Processor') and CounterName == '% Processor Time' and InstanceName in ('_Total', 'total');
let CpuObject = toscalar(CpuRaw | summarize Info = countif(ObjectName == 'Processor Information') | project iff(Info > 0, 'Processor Information', 'Processor'));
let Cpu = CpuRaw | where ObjectName == CpuObject | project TimeGenerated, Value = todouble(CounterValue);
let MemRaw = Perf
| where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M and ObjectName == 'Memory';
let MemPct = MemRaw | where CounterName in ('% Committed Bytes In Use', '% Used Memory') | project TimeGenerated, Value = todouble(CounterValue);
let MemAvailGb = MemRaw | where CounterName in ('Available MBytes', 'Available MBytes Memory') | project TimeGenerated, Value = todouble(CounterValue) / 1024.0;
let DiskInsights = InsightsMetrics
| where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M and Origin == 'vm.azm.ms' and Namespace == 'LogicalDisk' and Name in ('FreeSpacePercentage', 'FreeSpaceMB')
| extend Volume = tostring(todynamic(Tags)['vm.azm.ms/mountId']), SizeMB = todouble(todynamic(Tags)['vm.azm.ms/diskSizeMB'])
| where isnotempty(Volume)
| project TimeGenerated, Volume, Metric = iff(Name == 'FreeSpacePercentage', 'Pct', 'FreeMB'), Value = todouble(Val), SizeMB;
let DiskPerfVolumes = Perf
| where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M and ObjectName in ('Logical Disk', 'LogicalDisk') and CounterName in ('% Free Space', 'Free Megabytes')
| where InstanceName !in ('_Total', 'total')
| where not(InstanceName startswith '/snap/' or InstanceName startswith '/run' or InstanceName startswith '/dev' or InstanceName startswith '/sys' or InstanceName startswith '/proc' or InstanceName startswith '/var/lib/snapd' or InstanceName startswith '/var/snap')
| project TimeGenerated, Volume = InstanceName, Metric = iff(CounterName == '% Free Space', 'Pct', 'FreeMB'), Value = todouble(CounterValue), SizeMB = double(null);
let DiskVolumes = union DiskInsights, DiskPerfVolumes;
let DiskAggregate = Perf
| where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M and ObjectName in ('Logical Disk', 'LogicalDisk') and CounterName == '% Free Space' and InstanceName in ('_Total', 'total')
| where toscalar(DiskVolumes | take 1 | count) == 0
| project TimeGenerated, Volume = 'All volumes (aggregate)', Metric = 'Pct', Value = todouble(CounterValue), SizeMB = double(null);
let Disk = union DiskVolumes, DiskAggregate;
let Beats = Heartbeat | where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M;
let LastBeat = toscalar(Beats | summarize max(TimeGenerated));
let CpuNow = toscalar(Cpu | summarize arg_max(TimeGenerated, Value) | project Value);
let CpuP95 = toscalar(Cpu | summarize percentile(Value, 95));
let CpuPeak = toscalar(Cpu | summarize max(Value));
let MemNow = toscalar(MemPct | summarize arg_max(TimeGenerated, Value) | project Value);
let AvailNow = toscalar(MemAvailGb | summarize arg_max(TimeGenerated, Value) | project Value);
let DiskLowest = DiskVolumes | where Metric == 'Pct' | summarize arg_max(TimeGenerated, Value) by Volume | summarize arg_min(Value, Volume);
let DiskPct = toscalar(DiskLowest | project Value);
let DiskVol = toscalar(DiskLowest | project Volume);
let WinEvents = Event | where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M | project TimeGenerated, IsError = EventLevelName in ('Error', 'Critical');
let LinuxLogs = Syslog | where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M | project TimeGenerated, IsError = SeverityLevel in ('emerg', 'alert', 'crit', 'err', 'error');
let Logs = union WinEvents, LinuxLogs | summarize Total = count(), Errors = countif(IsError);
let LogTotal = toscalar(Logs | project Total);
let LogErrors = toscalar(Logs | project Errors);
let HasBeat = isnotnull(LastBeat);
print Dummy = 1
| project data = pack_array(
    pack('Label', 'Last heartbeat', 'Value', iff(HasBeat, AgeText(LastBeat), 'No heartbeat'), 'Note', iff(HasBeat, iff(datetime_diff('minute', now(), LastBeat) <= 5, 'agent is reporting', 'not reporting now'), 'no heartbeat in this range'), 'Order', 1),
    pack('Label', 'CPU (latest)', 'Value', iff(isnotnull(CpuNow), strcat(Num(CpuNow, 1), '%'), 'No data'), 'Note', iff(isnotnull(CpuNow), strcat('P95 ', Num(CpuP95, 0), '% / peak ', Num(CpuPeak, 0), '%'), 'No CPU samples in this range'), 'Order', 2),
    pack('Label', 'Memory in use', 'Value', iff(isnotnull(MemNow), strcat(Num(MemNow, 1), '%'), 'No data'), 'Note', iff(isnotnull(AvailNow), strcat(Num(AvailNow, 1), ' GB available'), 'No memory samples in range'), 'Order', 3),
    pack('Label', 'Lowest disk free', 'Value', iff(isnotnull(DiskPct), strcat(Num(DiskPct, 0), '%'), 'No data'), 'Note', iff(isnotnull(DiskPct), strcat('on volume ', DiskVol), 'No disk samples in this range'), 'Order', 4),
    pack('Label', 'Log events', 'Value', iff(isnotnull(LogTotal) and LogTotal > 0, tostring(LogTotal), 'No data'), 'Note', iff(isnotnull(LogTotal) and LogTotal > 0, strcat(LogErrors, ' errors in this range'), 'No log rows in this range'), 'Order', 5))
| mv-expand data
| project Label = tostring(data.Label), Value = tostring(data.Value), Note = tostring(data.Note), Order = toint(data.Order)
| order by Order asc
| project Label, Value, Note

