let WinEvents = Event | where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M | where EventLevelName in ('Error', 'Critical', 'Warning') | project TimeGenerated, Severity = iff(EventLevelName == 'Warning', 'Warning', 'Error');
let LinuxLogs = Syslog | where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M | where SeverityLevel in ('emerg', 'alert', 'crit', 'err', 'error', 'warning') | project TimeGenerated, Severity = iff(SeverityLevel == 'warning', 'Warning', 'Error');
union WinEvents, LinuxLogs
| make-series Events = count() default = 0 on TimeGenerated from bin(WindowStart, Step) to bin(WindowEnd, Step) + Step step Step by Severity

let M = tolower(tostring(split('{Machine}', '/')[-1]));
let WindowStart = todatetime('{TimeRange:startISO}');
let WindowEnd = todatetime('{TimeRange:endISO}');
let WindowSpan = WindowEnd - WindowStart;
let Step = case(WindowSpan <= 6h, 10m, WindowSpan <= 2d, 1h, WindowSpan <= 8d, 2h, WindowSpan <= 16d, 6h, 12h);
let Num = (v:real, digits:int) { replace_regex(tostring(round(v, digits)), @"\.0+$", "") };
let AgeText = (ts:datetime) {
    let mins = datetime_diff('minute', now(), ts);
    case(isnull(ts), 'none', mins < 2, 'just now', mins < 120, strcat(mins, ' min ago'), mins < 2880, strcat(Num(mins / 60.0, 1), ' h ago'), strcat(Num(mins / 1440.0, 1), ' d ago'))
};
let WinEvents = Event | where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M | project TimeGenerated, Log = EventLog, Source, Severity = case(EventLevelName in ('Error', 'Critical'), 'Error', EventLevelName == 'Warning', 'Warning', 'Information');
let LinuxLogs = Syslog | where TimeGenerated between (WindowStart .. WindowEnd) and Computer =~ M | project TimeGenerated, Log = Facility, Source = ProcessName, Severity = case(SeverityLevel in ('emerg', 'alert', 'crit', 'err', 'error'), 'Error', SeverityLevel == 'warning', 'Warning', 'Information');
union WinEvents, LinuxLogs
| summarize Errors = countif(Severity == 'Error'), Warnings = countif(Severity == 'Warning'), Information = countif(Severity == 'Information'), Last = max(TimeGenerated) by Log, Source
| order by Errors desc, Warnings desc, Information desc
| take 25
| project Log, Source, Errors, Warnings, Last
